solution_1:
思路
折半搜索。

看数据范围，2 
46
  肯定炸，但 2×2 
23
  炸不了。

整个数组从中间劈成两半，对于每一半，求出礼物能组成的所有重量数，存在两个数组中。

把其中一个数组排序，遍历另一个数组，二分查找在另一个数组中满足条件的最大值。最后求出所有答案的最大值。

代码
#include<bits/stdc++.h>
using namespace std;
#define ll long long
#define ull unsigned long long
#define INF 0x3f3f3f3f
#define re register
#define ri register int
#define rll register long long
#define ld long double
#define endl '\n'
#define fi first
#define se second
#define pii pair<int,int>
#define p_q priority_queue
#define iter iterator
#define rep(i,a,b) for(int i=(a);i<=(b);i++)
#define nep(i,a,b) for(int i=(a);i>=(b);i--)
#define popcount __builtin_popcount
#define pb push_back
#define mem(a,x) memset((a),x,sizeof(a))
#define eps 1e-8
#define oper operator
#define mk make_pair
vector<ll>a,b;
ll n,g[55],w;
void dfs1(int l,int r,ll sum){
	if(l>r){
		if(sum<=w)a.pb(sum);//能搬动
		return ;
	}
	dfs1(l+1,r,sum+g[l]);
	dfs1(l+1,r,sum);
}
void dfs2(int l,int r,ll sum){
	if(l>r){
		if(sum<=w)b.pb(sum);//能搬动
		return ;
	}
	dfs2(l+1,r,sum+g[l]);
	dfs2(l+1,r,sum);
}
int main(){
	cin>>w>>n;
	for(int i=1;i<=n;i++) cin>>g[i];
	dfs1(1,(1+n)/2,0);//前一半
	dfs2((1+n)/2+1,n,0);//后一半
	ll maxx=0;
	sort(b.begin(),b.end());//排序
	for(int i=0;i<a.size();i++){
		ll sum=a[i];
		int l=0,r=b.size()-1,ans=0;
		while(l<=r){//二分查找满足条件的最大值
			int mid=(l+r)/2;
			if(b[mid]+a[i]<=w){
				l=mid+1;
				ans=mid;
			}else r=mid-1;
		}
		sum+=b[ans];
		maxx=max(maxx,sum);
	}
	cout<<maxx;//输出
    return 0;
}

solution_2:
来一发双向搜索加双指针的题解。

题目大意
分析一下复杂度。

暴力搜索 O(2 
n
 ) 明显会炸，但是 O(2 
2
n
​
 +1
 ) 不会，所以双向搜索可行。

题目实现
劈成两半枚举所有可能的结果，每一半存入一个数组中。

最后从两个数组中分别拿出一个匹配，如果不超过 W，那么是一个可能的答案，统计最大值。

但是显然 O(n 
2
 ) 的答案求解不可行，所以考虑食用双指针优化为 O(n)。

我们将两个数组从大到小排序，显然对于第一个数组 a，随着下标不断增大，a 
i
​
  也不断增大，根据单调性，如果想要两个数的和维持在 ≤W 的范围内，第二个数要不断缩小，所以我们可以再设一个指针 j 来倒序枚举第二个数组。

代码：
#include <bits/stdc++.h>
#define int long long
#define f(i ,m ,n ,x) for (int i = (m) ;i <= (n) ;i += (x))
using namespace std ;
template < typename T > inline void read (T &x) {
	x = 0 ;
	bool flag (0) ;
	register char ch = getchar () ;
	while (! isdigit (ch)) {
		flag = ch == '-' ;
		ch = getchar () ;
	}
	while (isdigit (ch)) {
		x = (x << 1) + (x << 3) + (ch ^ 48) ;
		ch = getchar () ;
	}
	flag ? x = -x : 0 ;
}
const int N = 50 ;
const int M = (1 << 23) + 7 ;
int w ,n ,g[N] ;
int v1[M] ,v2[M] ,tot1 ,tot2 ,mid ;
inline void dfs (int num ,int end ,int sum ,bool flag) {
	if (num == end + 1) {
		if (! flag) {
			v1[++ tot1] = sum ;
			return ;
		}
		v2[++ tot2] = sum ;
		return ;
	}
	dfs (num + 1 ,end ,sum ,flag) ;
	if (sum + g[num] <= w) {
		dfs (num + 1 ,end ,sum + g[num] ,flag) ;
	} // 第 num 个物品可以选或者不选
}
int ans ;
signed main () {
	read (w) ,read (n) ;
	f (i ,1 ,n ,1) {
		read (g[i]) ;
	}
	mid = n >> 1 ;
	dfs (1 ,mid ,0 ,0) ;
	dfs (mid + 1 ,n ,0 ,1) ;
	int j = tot2 ;
	sort (v1 + 1 ,v1 + tot1 + 1) ;
	sort (v2 + 1 ,v2 + tot2 + 1) ;
	f (i ,1 ,tot1 ,1) {
		while (j >= 1 && v2[j] + v1[i] > w) j -- ;
		ans = max (ans ,v2[j] + v1[i]) ;
	}
	cout << ans << '\n' ;
	return 0 ;
}
